'use strict';
const $ = s => document.querySelector(s);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {home:'m3 10 9-7 9 7v10H4V10m5 10v-7h6v7',book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-6-2-10 1zm0 0v15',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7.9a4 4 0 0 1 0 7.8',user:'M20 21v-2a7 7 0 0 0-14 0v2m7-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8',plus:'M12 5v14M5 12h14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12h4',search:'M21 21l-5-5M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',chevron:'m9 5 7 7-7 7',chart:'M4 20V10m8 10V4m8 16v-7',chat:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4M8 10h8m-8 4h5',support:'M3 14v-3a9 9 0 0 1 18 0v3M3 12h4v7H3zm14 0h4v7h-4zm3 7c0 3-4 3-7 3',briefcase:'M3 7h18v14H3zm5 0V3h8v4M3 12c5 4 13 4 18 0m-9 1v4',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m0-6v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',laptop:'M4 3h16v13H4zm-2 17 2-4h16l2 4z',bulb:'M9 18h6m-5 3h4M8 14a7 7 0 1 1 8 0l-1 4H9z',wallet:'M3 6h17v15H3zm0 0V3h14v3m3 6h-6v5h6m-3-2.5h.1',play:'m9 5 11 7-11 7z',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',bookmark:'M6 3h12v19l-6-4-6 4z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12m10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',close:'m6 6 12 12M6 18 18 6',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',leaf:'M20 3C8 1 1 9 6 17c8 5 16-2 14-14ZM3 21 15 9',wind:'M3 8h12a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M3 17h6a3 3 0 1 1-3 3',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6zm-4 10 3 3 5-6',award:'M12 3a6 6 0 1 0 0 12 6 6 0 0 0 0-12m-4 11-2 8 6-3 6 3-2-8',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',logout:'M9 3H3v18h6m-1-9h13m-5-5 5 5-5 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 0c-6 5-6 13 0 18 6-5 6-13 0-18M3 12h18',wifi:'M3 7c5-5 13-5 18 0M6 11c3-3 9-3 12 0m-9 4c2-2 4-2 6 0m-3 4h.1',edit:'m16 3 5 5L9 20l-6 1 1-6zm-2 2 5 5'};
const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.book}"/></svg>`;
const art = '<img src="assets/illustrations/student-premium.png" alt="Young woman with braids and a yellow hoodie, learning with her laptop among flowers">';
const defaults = {accounts:[],session:null,profiles:{},onboarded:false};
let db;try{db=JSON.parse(localStorage.getItem('youth360-v1'))||structuredClone(defaults)}catch{db=structuredClone(defaults)}
const fresh = () => ({name:'',contact:'',bio:'Learning, growing, finding my way.',completed:[],downloads:[],courses:[],resources:[],saved:[],checkins:[],ideas:[],replies:{},votes:{},likes:[],goals:[],settings:{notifications:true,accessibility:false,dataSaver:false,offline:false,language:'English'}});
let profile=db.profiles[db.session] || fresh(), route='splash', params={}, history=[], onboard=0, selectedMood=null, toastTimer, lastFocus;
const persist = () => {if(db.session)db.profiles[db.session]=profile;try{localStorage.setItem('youth360-v1',JSON.stringify(db));return true}catch{toast('Storage is unavailable. Changes will last for this session only.');return false}};
const courses=[{id:'digital',title:'Digital Skills',desc:'Learn at your own pace',category:'Courses',icon:'laptop',lessons:['Computer Basics','Internet Safety','Finding reliable information','Email essentials','Creating documents','Working with spreadsheets','Presenting your ideas','Cloud storage','Digital communication','Online collaboration','Your digital footprint','Put your skills to work']},{id:'career',title:'Career Preparation',desc:'CVs, interviews & more',category:'Career',icon:'briefcase',lessons:['Discover your strengths','Build your first CV','Write a cover letter','Prepare for interviews']},{id:'business',title:'Entrepreneurship',desc:'Turn your ideas into action',category:'Career',icon:'bulb',lessons:['Find a problem to solve','Know your customers','Plan your first business','Pitch your idea']},{id:'money',title:'Financial Literacy',desc:'Money skills for life',category:'Life Skills',icon:'wallet',lessons:['Your first budget','Needs and wants','Building a savings habit','Understanding borrowing']}];
const opportunities=[{id:'bursary',title:'Your next chapter bursary',category:'Bursaries',type:'Bursaries',desc:'A sample study-funding opportunity for South African matric learners.',deadline:'30 November 2026',icon:'book'},{id:'job',title:'Junior digital internship',category:'Jobs',type:'Jobs & Internships',desc:'Explore what a first digital workplace experience could look like.',deadline:'15 December 2026',icon:'laptop'},{id:'event',title:'Build your first CV workshop',category:'Events',type:'Workshops & Events',desc:'A sample community workshop for young people preparing for work.',deadline:'10 October 2026',icon:'users'},{id:'competition',title:'Ideas for your neighbourhood',category:'Events',type:'Competitions',desc:'Imagine a practical idea that could improve your community.',deadline:'20 November 2026',icon:'bulb'},{id:'learnership',title:'Customer service learnership',category:'Jobs',type:'Learnerships',desc:'A sample work-and-learning pathway for young South Africans.',deadline:'5 December 2026',icon:'briefcase'},{id:'volunteer',title:'Community reading buddy',category:'Events',type:'Volunteering',desc:'A sample volunteering role supporting a love of reading.',deadline:null,icon:'heart'}];
const resources={
 'Mental Health':{icon:'heart',category:'Mental Health',text:'Make room for how you feel. You do not have to figure everything out today.',tips:['Name one feeling without judging it.','Choose one small task you can manage.','Reach out to someone you trust when you need support.']},
 'Physical Health':{icon:'sun',category:'Physical Health',text:'Find everyday movement that feels comfortable and enjoyable for you.',tips:['Take a gentle movement break between study sessions.','Choose an activity you enjoy.','Rest when you need to.']},
 'Nutrition':{icon:'leaf',category:'Nutrition',text:'Make time for regular meals and water when you can.',tips:['Plan a simple meal using what is available.','Keep water nearby while studying.','Ask a trusted local service about food support if you need it.']},
 'Sleep':{icon:'moon',category:'Sleep',text:'Build a wind-down routine that works for your day.',tips:['Set aside a quiet moment before bed.','Write down tomorrow’s tasks to clear your mind.','Make your resting space comfortable where possible.']},
 'Breathing Exercises':{icon:'wind',category:'Mental Health',text:'A quiet moment for yourself. Follow the circle at a comfortable pace; breathe normally if this does not feel comfortable.',tips:['Sit comfortably and relax your shoulders.','Let the circle guide a gentle breath in and out.','Stop whenever you want.']},
 'Self-Care Tips':{icon:'heart',category:'Physical Health',text:'Self-care can be small, practical and free.',tips:['Take a short break.','Make time for something you enjoy.','Ask for help with a task that feels too big.']},
 'Positive Affirmations':{icon:'sun',category:'Mental Health',text:'“I am allowed to learn at my own pace.”',tips:['“My voice deserves to be heard.”','“One small step is still progress.”','“I can ask for support.”']},
 'Talk to Someone':{icon:'support',category:'Mental Health',text:'You deserve to be listened to. Think of a trusted person you feel safe talking to.',tips:['Choose a time and place where you feel comfortable.','Try: “I have something on my mind. Can we talk?”','If the first person cannot help, try another trusted person or service.']},
 'Stress Management':{icon:'leaf',category:'Mental Health',text:'Create a little space when things feel busy.',tips:['Write down what is on your mind.','Separate what you can do today from what can wait.','Take one manageable step, then pause.']},
 'Healthy Habits':{icon:'target',category:'Nutrition',text:'Start with a habit small enough to fit your real life.',tips:['Pick one simple daily action.','Link it to something you already do.','Notice your effort, even when a day does not go to plan.']}
};
const topics=['Education in my community','Youth employment','What support do you need?','Community safety','Digital access'];
const moodNames=['Very good','Good','Okay','Low','Very low'];
function face(i){return `<svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="20" fill="${i<2?'#FFC329':i===2?'#FAF9F6':'#F3F4F6'}" stroke="#111827" stroke-width="1.7"/><path d="M17 19v2m14-2v2" stroke="#111827" stroke-width="2.5" stroke-linecap="round"/><path d="${['M15 28q9 12 18 0Z','M16 29q8 8 16 0','M17 31h14','M17 33q7-7 14 0','M16 34q8-12 16 0'][i]}" fill="none" stroke="#111827" stroke-width="1.7" stroke-linecap="round"/></svg>`}
const moods = (inline=false) => `<div class="moods" role="group" aria-label="Choose your mood">${moodNames.map((n,i)=>`<button class="mood ${selectedMood===i?'selected':''}" data-action="${inline?'check-mood':'mood'}" data-id="${i}" aria-pressed="${selectedMood===i}">${face(i)}<span>${n}</span></button>`).join('')}</div>`;
const button=(text,action,id='',style='')=>`<button class="btn ${style}" data-action="${action}" data-id="${escapeHTML(id)}">${text}</button>`;
const menu=(text,ico,action,id='')=>`<button class="menu-row" data-action="${action}" data-id="${escapeHTML(id)}">${icon(ico)}<span>${escapeHTML(text)}</span>${icon('chevron')}</button>`;
const tabs=(values,current)=>`<div class="tabs" role="tablist">${values.map(v=>`<button class="tab ${v===current?'active':''}" role="tab" aria-selected="${v===current}" data-action="tab" data-id="${v}">${v}</button>`).join('')}</div>`;
function header(title,sub=''){return `<div class="top"><button class="icon-button" data-action="back" aria-label="Go back">${icon('back')}</button><span class="eyebrow" style="margin:0">YOUR SPACE TO GROW</span><button class="icon-button" data-action="notifications" aria-label="Notifications">${icon('bell')}</button></div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}`}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function go(next,p={},back=false){closeSheet();if(!back&&route!==next)history.push({route,params});route=next;params=p;render();$('#screen').scrollTo?.(0,0)}
function nav(){
 let active=route;
 if(['course','saved-courses'].includes(route))active='learn';
 if(['resource','checkin','checkin-history'].includes(route))active='wellbeing';
 if(route==='discussion')active='community';
 if(['settings','progress','saved','edit-profile'].includes(route))active='profile';
 const hidden=['splash','onboarding','signup','login'].includes(route);
 $('#nav').innerHTML=hidden?'':[['learn','Learn','book'],['wellbeing','Wellbeing','heart'],['home','Home','home'],['community','Community','users'],['profile','Profile','user']].map(([r,t,i])=>`<button class="nav-item ${r==='home'?'nav-home ':''}${active===r?'active':''}" data-action="nav" data-id="${r}" ${active===r?'aria-current="page"':''}><span>${icon(i)}</span>${t}</button>`).join('');
 $('#app').classList.toggle('has-nav',!hidden);
}

function render(){document.title=`Youth360 · ${route.replaceAll('-',' ')}`;$('#app').classList.toggle('large-text',!!profile.settings.accessibility);let html='';const tab=params.tab||'All';
 if(route==='splash')html=`<div class="splash"><span class="wordmark">youth<span>360</span><i></i></span>${art}<p>Learn · Grow · Be Well · Be Heard</p></div>`;
 else if(route==='onboarding'){let titles=['Learn','Be Well','Grow','Be Heard'],copy=['Gain practical skills for your future.','Take care of your mind, body and yourself.','Build your confidence and opportunities.','Your ideas matter. Make a difference.'];html=`<div class="onboarding"><div class="row"><span class="wordmark">youth<span>360</span><i></i></span><button class="text-button" data-action="skip">Skip</button></div>${art}<div class="eyebrow">0${onboard+1} / ${['LEARN','BE WELL','GROW','BE HEARD'][onboard]}</div><h1>${titles[onboard]}</h1><p class="subtitle">${copy[onboard]}</p><div class="onboarding-footer"><div class="dots">${titles.map((_,i)=>`<button class="${i===onboard?'active':''}" data-action="onboard-dot" data-id="${i}" aria-label="Onboarding page ${i+1}" ${i===onboard?'aria-current="step"':''}></button>`).join('')}</div><div class="onboarding-controls"><button class="btn secondary" data-action="onboard-prev" ${onboard===0?'disabled':''}>${icon('back')} Previous</button>${button(onboard===3?'Get Started':`Next ${icon('arrow')}`,'onboard-next')}</div></div></div>`}
 else if(route==='signup'||route==='login'){let signup=route==='signup';html=`<div class="auth"><div class="top"><span class="wordmark">youth<span>360</span><i></i></span><span class="chip">Your next chapter</span></div><div class="auth-art">${art.replace('<img','<img class="auth-art"')}</div><h1>${signup?'Create your account':'Welcome Back!'}</h1><p class="subtitle">${signup?'A space for your learning, wellbeing and big ideas.':'Your next small step is waiting for you.'}</p><form id="auth-form" novalidate>${signup?'<label for="name">Full name</label><input id="name" name="name" autocomplete="name" placeholder="Your full name" required>':''}<label for="contact">Email or phone number</label><input id="contact" name="contact" autocomplete="username" placeholder="you@example.com or 082 123 4567" required><label for="password">Password</label><div class="password"><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" placeholder="${signup?'At least 8 characters':'Your password'}" required><button type="button" data-action="password" data-id="password" aria-label="Show password">${icon('eye')}</button></div>${signup?`<label for="confirm">Confirm password</label><div class="password"><input id="confirm" name="confirm" type="password" autocomplete="new-password" placeholder="Repeat your password" required><button type="button" data-action="password" data-id="confirm" aria-label="Show confirm password">${icon('eye')}</button></div>`:'<div style="text-align:right"><button type="button" class="text-button" data-action="forgot">Forgot password?</button></div>'}<div class="form-error" role="alert"></div><button class="btn" type="submit">${signup?'Sign Up':'Sign in'} ${icon('arrow')}</button></form><p class="auth-footer">${signup?'Already have an account?':'New to Youth360?'} <button data-action="nav" data-id="${signup?'login':'signup'}">${signup?'Sign in':'Create account'}</button></p>${button('Continue as guest','demo','','secondary')}<p class="privacy-caption">Your account and progress are stored on this device. Use a unique password.</p></div>`}
 else if(route==='home'){html=`<header class="landing-header"><div class="landing-top"><span class="wordmark">youth<span>360</span><i></i></span><div class="header-actions"><button class="icon-button" data-action="quick" aria-label="Open quick actions">${icon('plus')}</button><button class="icon-button" data-action="notifications" aria-label="Notifications">${icon('bell')}<i class="notification-dot"></i></button></div></div><div class="illustrated-heading"><div><h1>Hi, ${escapeHTML(profile.name.split(' ')[0]||'there')}!</h1><p>Good to see you today.</p><span class="header-caption">Learn. Grow.<br>Make today yours.</span></div>${art}</div></header><div class="search">${icon('search')}<input id="search" aria-label="Search Youth360" placeholder="What would you like to do today?"></div><div class="row section-heading"><h2>Your space to grow</h2><span class="small">One step at a time</span></div><div class="grid" id="features">${featureGrid('')}</div><div id="search-empty" class="empty" hidden>No matches. Try learning or support.</div><div class="card check-card"><div class="row"><div><h2>Daily check-in</h2><p>How are you feeling today?</p></div>${icon('sun')}</div>${moods(true)}</div><div class="growth-card"><div><span class="eyebrow">A LITTLE EVERY DAY</span><h2>Keep going!</h2><p>Small steps make<br>a big difference.</p><button class="text-button" data-action="nav" data-id="learn">Find your next step ${icon('arrow')}</button></div></div>`}

 else if(route==='learn'||route==='saved-courses'){html=header(route==='learn'?'Learning Hub':'My Courses','Build skills for your future.')+(route==='learn'?`<div class="learning-banner">${art}</div>`+tabs(['All','Courses','Life Skills','Career'],tab):'')+courses.filter(c=>route==='saved-courses'?profile.courses.includes(c.id)||profile.completed.some(v=>v.startsWith(c.id+':')):tab==='All'||tab===c.category).map(courseCard).join('');if(route==='saved-courses'&&!profile.courses.length&&!profile.completed.length)html+='<p class="empty">Save a course from its lesson page to find it here.</p>'}
 else if(route==='course'){let c=courses.find(c=>c.id===params.id)||courses[0],n=params.lesson||0,key=c.id+':'+n,done=profile.completed.includes(key),count=profile.completed.filter(v=>v.startsWith(c.id+':')).length;html=header(c.title,`Lesson ${n+1} of ${c.lessons.length}`)+`<div class="video">${art}<button class="icon-button" data-action="video" aria-label="Open lesson preview">${icon('play')}</button><small>Video lesson - Coming soon</small></div><div class="row" style="margin-top:18px"><span class="small">${count} of ${c.lessons.length} lessons complete</span><strong class="small">${Math.round(count/c.lessons.length*100)}%</strong></div><div class="progress"><span style="width:${count/c.lessons.length*100}%"></span></div><h2>${c.lessons[n]}</h2>${tabs(['Video','Notes','Activities'],params.tab||'Video')}<div class="lesson-copy">${params.tab==='Notes'?`<h3>Your lesson notes</h3><p>Keep a useful idea from this lesson, or write down something you want to practise.</p><label for="lesson-notes">Personal notes</label><textarea id="lesson-notes">${escapeHTML((profile.notes||{})[key]||'')}</textarea>${button('Save notes','save-notes',key)}`:params.tab==='Activities'?`<h3>Try it yourself</h3><p>Write one way you could use ${escapeHTML(c.lessons[n].toLowerCase())} in your daily life.</p><label for="activity">Your response</label><textarea id="activity">${escapeHTML((profile.activities||{})[key]||'')}</textarea>${button('Save activity','save-activity',key)}`:`<p>${lessonDescription(c,n)}</p><p class="info-note">Put what you learn into practice with an activity.</p>`}</div>${button(done?`${icon('check')} Completed`:'Mark Complete','complete',key)}${button(n<c.lessons.length-1?'Continue '+icon('arrow'):'Back to Learning Hub','continue',c.id,'secondary')}<div class="row" style="margin-top:16px"><button class="text-button" data-action="download" data-id="${key}">${profile.downloads.includes(key)?'Available offline': 'Keep lesson on this device'}</button><button class="text-button" data-action="save-course" data-id="${c.id}">${profile.courses.includes(c.id)?'Course saved':'Save course'}</button></div>${n<c.lessons.length-1?`<div class="next"><div class="eyebrow">UP NEXT</div><button class="list-card" data-action="continue" data-id="${c.id}"><span class="icon-tile">${icon('play')}</span><div><h3>${c.lessons[n+1]}</h3><p>Lesson ${n+2} · 8 min</p></div>${icon('chevron')}</button></div>`:''}`}
 else if(route==='wellbeing'){html=`<header class="wellbeing-header"><div class="landing-top"><button class="icon-button" data-action="back" aria-label="Go back">${icon('back')}</button><button class="icon-button" data-action="notifications" aria-label="Notifications">${icon('bell')}</button></div><div class="illustrated-heading"><div><h1>Wellbeing</h1><p>Take care of your mind,<br>body and your future.</p><button class="text-button" data-action="nav" data-id="checkin">Check in with yourself ${icon('arrow')}</button></div>${art}</div></header><h2 class="section-heading">A little care for you</h2><div class="grid" style="grid-template-columns:repeat(2,1fr)">${['Mental Health','Physical Health','Nutrition','Sleep'].map(n=>`<button class="feature" data-action="resource" data-id="${n}"><span class="icon-tile">${icon(resources[n].icon)}</span>${n}</button>`).join('')}</div><div class="card"><h2>Daily emotional check-in</h2><p>How are you feeling today?</p>${moods(true)}</div><h2 class="section-heading">Your wellbeing toolkit</h2>${Object.keys(resources).slice(4).map(n=>menu(n,resources[n].icon,'resource',n)).join('')}<div class="notice"><strong>Need support right now?</strong><p>These are general wellbeing resources. They are not a counselling or emergency service.</p>${button('Find urgent support','support-detail','Crisis support','secondary')}</div>`}
 else if(route==='resource'){let r=resources[params.id];html=header(params.id,'A moment for your wellbeing.')+`<div class="resource-hero">${params.id==='Breathing Exercises'?'<div class="breath" id="breath">Ready when you are</div>':icon(r.icon)}</div><p class="lesson-copy">${r.text}</p>${params.id==='Breathing Exercises'?button('Start breathing','breathe'):''}<div class="card">${r.tips.map((t,i)=>`<p style="margin-bottom:15px"><strong>0${i+1}</strong> &nbsp;${t}</p>`).join('')}</div>${button(profile.resources.includes(params.id)?'Saved · Available offline':'Save resource','save-resource',params.id,'secondary')}${params.id==='Talk to Someone'?button('Get Support','nav','support'):''}<p class="info-note">General wellbeing information for reflection, not personalised treatment or urgent support.</p>`}
 else if(route==='checkin'){html=header('How are you feeling today?','Every feeling belongs here.')+`<div class="resource-hero">${icon('heart')}</div><form id="checkin-form">${moods()}<label for="reflection">Anything you’d like to share?</label><textarea id="reflection" placeholder="A little about your day… (optional)" maxlength="1500"></textarea><p class="small" style="margin-top:10px">Only saved in this browser. No one monitors these entries.</p><div class="form-error" role="alert"></div><button class="btn" type="submit">Save Check-in ${icon('check')}</button></form>${button('Previous check-ins','nav','checkin-history','secondary')}`}
 else if(route==='checkin-history'){html=header('Your check-ins','A little space to notice how you’ve been.')+(profile.checkins.length?profile.checkins.slice().reverse().map(c=>`<div class="card"><div class="row"><div style="width:44px">${face(c.mood)}</div><div><h3>${moodNames[c.mood]}</h3><p>${new Date(c.date).toLocaleString('en-ZA',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}</p></div></div>${c.note?`<p>${escapeHTML(c.note)}</p>`:''}</div>`).join(''):'<div class="empty">Your story starts with a check-in.</div>')+button('Check in now','nav','checkin')}
 else if(route==='community'){let t=params.tab||'Discussions';html=header('Youth Voice','Your ideas. Real change.')+tabs(['Discussions','Surveys','Ideas'],t)+`<p class="info-note">Your responses are private to this device. Community publishing is not available yet.</p>`;if(t==='Discussions')html+=topics.map((t,i)=>`<button class="card list-card" data-action="discussion" data-id="${i}"><span class="icon-tile">${icon('chat')}</span><div><h3>${t}</h3><p>${[12,8,16,6,9][i]} sample voices · Join the conversation</p></div>${icon('chevron')}</button>`).join('');else if(t==='Surveys')html+=`<div class="card"><span class="chip">Community pulse</span><h2 style="margin-top:15px">What would help you take your next step?</h2><p>Choose the support that matters most to you.</p>${['Skills workshops','Study funding','Career guidance','Wellbeing support'].map((v,i)=>`<button class="poll-option ${profile.votes.support===i?'selected':''}" data-action="vote" data-id="${i}" aria-pressed="${profile.votes.support===i}">${v}${profile.votes.support===i?' · Your vote':''}</button>`).join('')}${profile.votes.support!==undefined?'<p class="small">Your choice is saved. Select another option to change it.</p>':''}</div>`;else html+=`<div class="card"><h2>What’s your big idea?</h2><form id="idea-form"><label for="idea">An idea for your community</label><textarea id="idea" maxlength="1000" required placeholder="What could we make better, together?"></textarea><button class="btn">Submit idea ${icon('arrow')}</button></form></div>${[{id:'sample',text:'A weekend study circle at our community library.',name:'Lerato · Sample idea'},...profile.ideas].map(i=>`<div class="card"><span class="eyebrow">${escapeHTML(i.name)}</span><p style="color:var(--black)">${escapeHTML(i.text)}</p><button class="text-button" data-action="like" data-id="${i.id}" aria-pressed="${profile.likes.includes(i.id)}">${profile.likes.includes(i.id)?'Supported':'Support this idea'} · ${(i.id==='sample'?18:0)+(profile.likes.includes(i.id)?1:0)}</button></div>`).join('')}`}
 else if(route==='discussion'){let i=Number(params.id);html=header(topics[i],'A conversation worth having.')+`<div class="card"><span class="eyebrow">YOUTH360 - COMMUNITY CONVERSATION</span><p>What is one change you would like to see when it comes to ${topics[i].toLowerCase()}? Share an experience or a practical suggestion.</p></div><div class="card"><h3>Thando · Sample response</h3><p>I would love more spaces where young people can ask questions and learn from each other.</p></div>${(profile.replies[i]||[]).map(t=>`<div class="card"><h3>${escapeHTML(profile.name)}</h3><p>${escapeHTML(t)}</p></div>`).join('')}<form id="reply-form"><label for="reply">Add your voice</label><textarea id="reply" required maxlength="1000" placeholder="Keep it kind. Leave out personal contact details."></textarea><button class="btn">Save response</button></form>`}
 else if(route==='support'){html=header('Get Support','You’re not alone.')+`<div class="notice"><strong>In immediate danger?</strong><p>Contact your local emergency services or ask a trusted person nearby to help you reach urgent care. This app cannot respond to emergencies.</p>${button('Crisis support information','support-detail','Crisis support','secondary')}</div>${['Chat with a counsellor','Find local services','Crisis support','Trusted resources','Education support','Career support'].map((n,i)=>menu(n,['chat','globe','shield','book','book','briefcase'][i],'support-detail',n)).join('')}<p class="info-note">Live counselling is not available here yet. Explore the support information below.</p>`}
 else if(route==='opportunities'){html=header('Opportunities','Jobs, bursaries, skills & more.')+tabs(['All','Jobs','Bursaries','Events'],tab)+`<p class="info-note">Explore possible pathways. These illustrative listings are not open for applications.</p>`+opportunities.filter(o=>tab==='All'||o.category===tab).map(opportunityCard).join('')}
 else if(route==='opportunity'){let o=opportunities.find(o=>o.id===params.id);html=header(o.title,o.type)+`<div class="resource-hero">${icon(o.icon)}</div><span class="chip">Illustrative opportunity</span><p class="lesson-copy">${o.desc}</p><div class="card"><h3>What this example could involve</h3><p>For young people in South Africa exploring their next step. A real listing would include an organiser, eligibility criteria, location and verified application link.</p><p><strong>Sample deadline:</strong> ${o.deadline||'No deadline'}</p></div><div class="notice">No applications are accepted. This listing demonstrates how opportunities will appear.</div>${button(profile.saved.includes(o.id)?'Saved opportunity':'Save opportunity','save-opportunity',o.id)}`}
 else if(route==='progress'){let t=params.tab||'Overview',total=courses.reduce((s,c)=>s+c.lessons.length,0),pct=Math.round(profile.completed.length/total*100),finished=courses.filter(c=>c.lessons.every((_,i)=>profile.completed.includes(c.id+':'+i))).length;html=header('My Progress','Look how far you’re growing.')+tabs(['Overview','Achievements','Goals'],t);if(t==='Overview')html+=`<div class="card" style="text-align:center"><h3>Overall learning progress</h3><div class="ring" style="--percent:${pct}%"><div><strong>${pct}%</strong><small>one step at a time</small></div></div><p>Your progress across all ${total} lessons.</p></div><div class="stats">${[[finished,'Courses completed'],[profile.completed.length,'Lessons completed'],[profile.checkins.length,'Wellbeing check-ins'],[achievementCount(),'Achievements earned']].map(([n,t])=>`<div class="card"><strong>${n}</strong><p>${t}</p></div>`).join('')}</div>${button('Keep learning','nav','learn')}`;else if(t==='Achievements')html+=[['First step','Complete your first lesson',profile.completed.length>0],['A moment for me','Save your first check-in',profile.checkins.length>0],['My voice matters','Share your first idea',profile.ideas.length>0]].map(([n,d,ok])=>`<div class="card list-card"><span class="icon-tile" style="${ok?'':'background:var(--grey-100)'}">${icon('award')}</span><div><h3>${n}</h3><p>${ok?'Earned · ':''}${d}</p></div>${ok?icon('check'):''}</div>`).join('');else html+=`<form class="card" id="goal-form"><h2>Make space for a goal</h2><label for="goal">What would you like to work towards?</label><input id="goal" required maxlength="160" placeholder="e.g. Complete my first course"><button class="btn">Add goal</button></form>${profile.goals.map((g,i)=>`<button class="card list-card" data-action="goal-toggle" data-id="${i}" aria-pressed="${g.done}"><span class="icon-tile">${icon(g.done?'check':'target')}</span><div><h3>${escapeHTML(g.text)}</h3><p>${g.done?'Achieved · Tap to reopen':'In progress · Tap when achieved'}</p></div></button>`).join('')}`}
 else if(route==='profile'){html=header('My space')+`<div class="profile-header"><div class="avatar portrait-avatar">${art}</div><h2>${escapeHTML(profile.name)}</h2><p>${escapeHTML(profile.bio)}</p></div>`+[['My Progress','chart','progress'],['My Courses','book','saved-courses'],['My Achievements','award','achievements'],['Saved Resources','bookmark','saved-resources'],['Saved Opportunities','briefcase','saved-opportunities'],['Check-in History','heart','checkin-history'],['Settings','settings','settings'],['Help & Support','support','support']].map(([t,i,r])=>menu(t,i,'profile-menu',r)).join('')+menu('Log Out','logout','logout')}
 else if(route==='saved'){let res=params.type==='resources';html=header(res?'Saved Resources':'Saved Opportunities','Keep the things that matter close.')+(res?profile.resources.map(n=>menu(n,resources[n].icon,'resource',n)).join(''):opportunities.filter(o=>profile.saved.includes(o.id)).map(opportunityCard).join(''));if(!(res?profile.resources:profile.saved).length)html+='<p class="empty">Nothing saved yet. Tap Save on something you want to come back to.</p>'}
 else if(route==='settings'){html=header('Settings','Make this space work for you.')+menu('Edit Profile','edit','nav','edit-profile')+[['Notifications','bell','notifications'],['Accessibility · Larger text','eye','accessibility'],['Data Saver','wifi','dataSaver'],['Offline Mode','download','offline']].map(([t,i,k])=>`<button class="menu-row" role="switch" aria-checked="${profile.settings[k]}" data-action="toggle" data-id="${k}">${icon(i)}<span>${t}</span><span class="toggle ${profile.settings[k]?'on':''}"></span></button>`).join('')+menu('Language · '+profile.settings.language,'globe','language')+menu('Privacy','shield','privacy')+menu('About Youth360','sun','about')+'<p class="info-note">Offline and download controls simulate availability. They do not install the app or cache it for offline launch. Notifications are in-app only.</p>'}
 else if(route==='edit-profile'){html=header('Edit Profile','A little about you.')+`<form id="profile-form"><label for="edit-name">Full name</label><input id="edit-name" value="${escapeHTML(profile.name)}" required maxlength="70"><label for="bio">About me</label><textarea id="bio" maxlength="180">${escapeHTML(profile.bio)}</textarea><button class="btn">Save changes</button></form>`}
 $('#screen').dataset.screen=route; $('#screen').innerHTML=(profile.settings.offline&&!['splash','onboarding','signup','login'].includes(route)?'<div class="offline-banner">Offline preference enabled</div>':'')+html;nav();
}
function initials(){return profile.name.split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('')||'Y'}
function achievementCount(){return Number(profile.completed.length>0)+Number(profile.checkins.length>0)+Number(profile.ideas.length>0)}
const features=[['Learning Hub','book','learn'],['Wellbeing','heart','wellbeing'],['My Progress','chart','progress'],['Youth Voice','chat','community'],['Get Support','support','support'],['Opportunities','briefcase','opportunities']];
function featureGrid(q){return features.filter(([n])=>n.toLowerCase().includes(q.toLowerCase())).map(([n,i,r])=>`<button class="feature" data-action="nav" data-id="${r}"><span class="icon-tile">${icon(i)}</span>${n}</button>`).join('')}
function courseCard(c){let done=profile.completed.filter(k=>k.startsWith(c.id+':')).length;return `<button class="card course-card" data-action="course" data-id="${c.id}"><span class="icon-tile">${icon(c.icon)}</span><div class="course-copy"><h3>${c.title}</h3><p>${c.desc}</p>${done?`<div class="progress"><span style="width:${done/c.lessons.length*100}%"></span></div><small>${done} of ${c.lessons.length} complete</small>`:''}</div>${icon('chevron')}</button>`}

function opportunityCard(o){return `<article class="card opportunity"><div class="row"><span class="eyebrow">${o.type}</span><span class="chip">Illustrative</span></div><h3>${o.title}</h3><p>${o.desc}</p><p class="small">${o.deadline?'Sample deadline: '+o.deadline:'Ongoing · Sample listing'}</p><div class="row"><button class="text-button" data-action="save-opportunity" data-id="${o.id}" aria-pressed="${profile.saved.includes(o.id)}">${profile.saved.includes(o.id)?'Saved':'Save'}</button>${button('View Details '+icon('arrow'),'opportunity',o.id,'compact')}</div></article>`}
function lessonDescription(c,n){if(c.id==='digital'&&n===0)return 'Meet the tools you’ll use every day: a keyboard for typing, a mouse or trackpad for navigation, and folders for keeping your work organised. Practise opening a document, giving it a clear name and saving it somewhere you can find again.';if(c.id==='digital'&&n===1)return 'Protect your online space. Use different passwords for your accounts, pause before opening unexpected links and avoid sharing private details with people you do not know. When something feels suspicious, ask someone you trust before continuing.';return `Explore ${c.lessons[n].toLowerCase()} through a practical example. Start by writing what you already know, identify one question you have, and choose a small action to practise today. This is a sample lesson in ${c.title.toLowerCase()}.`}
function sheet(title,body){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><button class="icon-button close" data-action="close" aria-label="Close dialog">${icon('close')}</button><h2 id="sheet-title">${title}</h2>${body}</section></div>`;document.body.style.overflow='hidden';$('.sheet').focus()}
function closeSheet(){if(!$('#overlay').innerHTML)return;$('#overlay').innerHTML='';document.body.style.overflow='';lastFocus?.focus()}
function toggleList(list,id,message){let n=list.indexOf(id);if(n>=0)list.splice(n,1);else list.push(id);persist();render();toast(n>=0?'Removed from saved items':message)}
function enterAccount(id){db.session=id;profile=db.profiles[id]||fresh();persist();history=[];go('home',{},true)}
document.addEventListener('click',e=>{if(e.target.classList.contains('sheet-backdrop'))return closeSheet();let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action,id=el.dataset.id;
 if(a==='nav'){if(id==='checkin')selectedMood=null;go(id)}
 else if(a==='back'){let prev=history.pop();go(prev?.route||'home',prev?.params||{},true)}
 else if(a==='quick')sheet('A small step, right now',`<p>What do you need today?</p>${[['Daily Check-in','heart','checkin'],['Ask for Support','support','support'],['Share Your Voice','chat','community'],['Find an Opportunity','briefcase','opportunities']].map(([t,i,r])=>menu(t,i,'nav',r)).join('')}`);
 else if(a==='close')closeSheet();
 else if(a==='onboard-dot'){onboard=Number(id);render()}
 else if(a==='skip'||a==='onboard-next'&&onboard===3){db.onboarded=true;persist();if(db.session)go('home');else{if(!db.profiles.demo)db.profiles.demo={...fresh(),name:'Naledi',contact:'Guest'};enterAccount('demo')}}
 else if(a==='onboard-next'){onboard=Math.min(3,onboard+1);render()}
 else if(a==='onboard-prev'){onboard=Math.max(0,onboard-1);render()}
 else if(a==='demo'){if(!db.profiles.demo)db.profiles.demo={...fresh(),name:'Naledi',contact:'Guest'};enterAccount('demo')}
 else if(a==='password'){let input=document.getElementById(id);input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')}
 else if(a==='forgot')sheet('Forgot your password?',`<p>Password recovery is not available yet. You can create an account with a different contact or continue as a guest.</p>${button('Continue as guest','demo')}`);
 else if(a==='notifications')sheet('Your little reminders',profile.settings.notifications?`<div class="card"><h3>A moment for yourself</h3><p>Your daily check-in is ready whenever you are.</p>${button('Check in','nav','checkin')}</div><p class="small">In-app reminder</p>`:'<p>In-app reminders are turned off. You can change this in Settings.</p>');
 else if(a==='tab'){params.tab=id;render()}
 else if(a==='course')go('course',{id,lesson:0});
 else if(a==='complete'){if(!profile.completed.includes(id)){profile.completed.push(id);persist();render();toast('Lesson complete. That’s another step forward!')}else toast('You’ve already completed this lesson.')}
 else if(a==='continue'){let c=courses.find(c=>c.id===id);if((params.lesson||0)<c.lessons.length-1){params.lesson=(params.lesson||0)+1;params.tab='Video';render();$('#screen').scrollTo?.(0,0)}else go('learn')}
 else if(a==='download')toggleList(profile.downloads,id,'Lesson saved on this device');
 else if(a==='save-course')toggleList(profile.courses,id,'Course saved to My Courses');
 else if(a==='save-notes'||a==='save-activity'){let key=a==='save-notes'?'notes':'activities';profile[key]??={};profile[key][id]=$(a==='save-notes'?'#lesson-notes':'#activity').value;persist();toast('Your work is saved')}
 else if(a==='video')sheet('Lesson preview',`<div class="resource-hero">${icon('play')}</div><p>This video is coming soon. Read the lesson or try the activity to continue learning.</p>${button('Back to lesson','close')}`);
 else if(a==='resource')go('resource',{id});
 else if(a==='save-resource')toggleList(profile.resources,id,'Resource saved · Saved on this device');
 else if(a==='mood'||a==='check-mood'){selectedMood=Number(id);if(a==='check-mood')go('checkin');else{document.querySelectorAll('.mood').forEach((m,i)=>{m.classList.toggle('selected',i===selectedMood);m.setAttribute('aria-pressed',i===selectedMood)})}}
 else if(a==='breathe'){let running=$('#breath').classList.toggle('running');$('#breath').textContent=running?'In as it grows. Out as it shrinks.':'Ready when you are';el.textContent=running?'Stop breathing exercise':'Start breathing'}
 else if(a==='discussion')go('discussion',{id});
 else if(a==='vote'){profile.votes.support=Number(id);persist();render();toast('Your vote is saved')}
 else if(a==='like')toggleList(profile.likes,id,'You supported this idea');
 else if(a==='support-detail'){let copy={'Chat with a counsellor':'Live chat is not available yet. For a conversation, ask a trusted adult, school support staff or a local counselling service how to get in touch.','Find local services':'Ask your school, local clinic, library or community centre about services nearby. Location search and a verified service directory are not available yet.','Crisis support':'If you are in immediate danger, contact your local emergency services or go to the nearest emergency department. If possible, stay with a trusted person who can help you reach urgent care. Youth360 cannot send help or monitor messages.','Trusted resources':'Your school, local clinic and public library can help you find trustworthy information and support. Check who publishes a resource and whether its contact details are current.','Education support':'Speak with school support staff about study groups, learning materials or study-funding guidance. You can also practise with the Learning Hub.','Career support':'Ask a school careers adviser or community service about CV support and training pathways. The Career Preparation course includes sample activities.'};sheet(id,`<p>${copy[id]}</p><p class="info-note">Information only · No request has been sent.</p>${button('Got it','close')}`)}
 else if(a==='opportunity')go('opportunity',{id});
 else if(a==='save-opportunity')toggleList(profile.saved,id,'Opportunity saved');
 else if(a==='goal-toggle'){profile.goals[Number(id)].done=!profile.goals[Number(id)].done;persist();render()}
 else if(a==='profile-menu'){if(id==='achievements')go('progress',{tab:'Achievements'});else if(id.startsWith('saved-')&&id!=='saved-courses')go('saved',{type:id.split('-')[1]});else go(id)}
 else if(a==='toggle'){profile.settings[id]=!profile.settings[id];persist();render();if(id==='dataSaver')toast(profile.settings[id]?'Data Saver on - Streaming media is disabled':'Data Saver off');if(id==='offline')toast('This preference is saved. Offline app launch is not available yet.')}
 else if(a==='language')sheet('Language',`<p>Youth360 is available in English. Other languages are planned.</p><label for="language">Display language</label><select id="language"><option>English</option></select>${button('Save preference','language-save')}`);
 else if(a==='language-save'){profile.settings.language=$('#language').value;persist();closeSheet();render();toast('Language preference saved')}
 else if(a==='privacy')sheet('Your privacy',`<p>Your profile, check-ins, saved items and responses are stored only in this browser’s localStorage. They are not sent to a server. Anyone using this browser profile may access them.</p><p>Passwords are stored as hashes on this device. Accounts do not sync across devices. Clearing browser site data removes accounts and progress.</p>`);
 else if(a==='about')sheet('Youth360',`<p>Learn · Grow · Be Well · Be Heard</p><p>Your space to learn, grow, be well and be heard. Version 1.0.</p><p>Learning, wellbeing and new possibilities, all in one place. Some services are still being prepared; illustrative opportunities are labelled.</p>`);
 else if(a==='logout'){db.session=null;persist();profile=fresh();history=[];go('login',{},true);toast('Signed out. Your progress is saved.')}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){let html=featureGrid(e.target.value);$('#features').innerHTML=html;$('#search-empty').hidden=!!html}});
async function passwordHash(value){const bytes=new TextEncoder().encode(value);if(globalThis.crypto?.subtle){const hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')}throw new Error('Please open the app through localhost or HTTPS to use your account. You can still continue as a guest.')}
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;
 if(form.id==='auth-form'){const contact=form.contact.value.trim().toLowerCase().replace(/\s/g,''),password=form.password.value,signup=route==='signup',error=form.querySelector('.form-error');error.textContent='';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact)&&!/^\+?\d{9,15}$/.test(contact)){error.textContent='Enter a valid email address or phone number.';return}if(password.length<8){error.textContent='Use a password with at least 8 characters.';return}if(signup&&(!form.elements.name.value.trim()||form.confirm.value!==password)){error.textContent=!form.elements.name.value.trim()?'Please enter your full name.':'The passwords do not match.';return}try{const hash=await passwordHash(password),account=db.accounts.find(a=>a.contact===contact);if(signup){if(account){error.textContent='This account already exists. Please sign in.';return}const id='user-'+Date.now();db.accounts.push({id,contact,hash});db.profiles[id]={...fresh(),name:form.elements.name.value.trim(),contact};enterAccount(id)}else{if(!account||account.hash!==hash){error.textContent='The contact or password does not match an account on this device.';return}enterAccount(account.id)}}catch(err){error.textContent=err.message}}
 else if(form.id==='checkin-form'){if(selectedMood===null){form.querySelector('.form-error').textContent='Choose a feeling before saving.';return}profile.checkins.push({mood:selectedMood,note:$('#reflection').value.trim(),date:new Date().toISOString()});persist();selectedMood=null;go('checkin-history');toast('Check-in saved. Thank you for making time for yourself.')}
 else if(form.id==='idea-form'){let text=$('#idea').value.trim();if(!text)return;profile.ideas.push({id:'idea-'+Date.now(),text,name:profile.name});persist();render();toast('Your idea is saved')}
 else if(form.id==='reply-form'){let text=$('#reply').value.trim();if(!text)return;(profile.replies[params.id]??=[]).push(text);persist();render();toast('Your response is saved')}
 else if(form.id==='goal-form'){let text=$('#goal').value.trim();if(!text)return;profile.goals.push({text,done:false});persist();render();toast('A new goal. A new beginning.')}
 else if(form.id==='profile-form'){let name=$('#edit-name').value.trim();if(!name)return;profile.name=name;profile.bio=$('#bio').value.trim();persist();go('profile');toast('Profile updated')}
});
document.addEventListener('keydown',e=>{if(!$('.sheet'))return;if(e.key==='Escape')closeSheet();if(e.key==='Tab'){const focusable=$('.sheet').querySelectorAll('button,input,textarea,select,a[href]'),first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.sheet'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.sheet'))){e.preventDefault();first.focus()}}});
let touchStart=null;document.addEventListener('touchstart',e=>{if(route==='onboarding')touchStart=e.changedTouches[0].clientX},{passive:true});document.addEventListener('touchend',e=>{if(route!=='onboarding'||touchStart===null)return;let dx=e.changedTouches[0].clientX-touchStart;if(Math.abs(dx)>55){onboard=Math.max(0,Math.min(3,onboard+(dx<0?1:-1)));render()}touchStart=null},{passive:true});
render();setTimeout(()=>{if(route==='splash')go('onboarding',{},true)},2000);
// Optional browser agent integration. The app remains independent of this API.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
 register({name:'youth360_open_screen',description:'Open a main Youth360 screen for the signed-in user.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['home','learn','wellbeing','community','opportunities','progress','profile','support','checkin']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const allowed=['home','learn','wellbeing','community','opportunities','progress','profile','support','checkin'];if(!db.session||!allowed.includes(input?.screen))throw new Error('Sign in and choose a supported screen.');go(input.screen);return {screen:route}}});
 window.addEventListener?.('pagehide',()=>lifecycle.abort(),{once:true});
}
